function validate([regions, region1, region2]) {
  if (!Array.isArray(regions) || regions.length < 2 || regions.length > 10000) return 'regions needs 2 to 10000 lists.';
  const nameOk = r => typeof r === 'string' && r.length >= 1 && r.length <= 20 && /^[A-Za-z ]+$/.test(r);
  const parent = new Map(), children = new Map(), names = new Set();
  for (const list of regions) {
    if (!Array.isArray(list) || list.length < 2 || list.length > 20) return 'Each list holds 2 to 20 regions.';
    if (!list.every(nameOk)) return 'Region names are 1 to 20 English letters (spaces allowed).';
    for (const r of list) names.add(r);
    if (!children.has(list[0])) children.set(list[0], []);
    for (let i = 1; i < list.length; i++) {
      if (parent.has(list[i])) return `"${list[i]}" is directly inside more than one region.`;
      parent.set(list[i], list[0]);
      children.get(list[0]).push(list[i]);
    }
  }
  if (!nameOk(region1) || !nameOk(region2)) return 'region1 and region2 are 1 to 20 English letters.';
  if (region1 === region2) return 'region1 and region2 must be different.';
  if (!names.has(region1) || !names.has(region2)) return 'region1 and region2 must both appear in regions.';
  const roots = [...names].filter(r => !parent.has(r));
  if (roots.length !== 1) return 'Exactly one region must contain all the others.';
  // Every region must be reachable from the root, which also rules out cycles.
  const queue = [roots[0]];
  for (let k = 0; k < queue.length; k++) for (const c of children.get(queue[k]) ?? []) queue.push(c);
  if (queue.length !== names.size) return 'Regions must not contain each other in a cycle.';
  return null;
}

