function findSmallestRegion(regions, region1, region2) {
  // For every region, list everything inside it; keep the smallest one that holds both regions.
  const children = new Map();
  const names = new Set(regions.flat());
  for (const [head, ...rest] of regions) children.set(head, (children.get(head) || []).concat(rest));
  const inside = r => [r, ...(children.get(r) || []).flatMap(inside)];
  let best = null;
  for (const r of names) {
    const all = inside(r);
    if (all.includes(region1) && all.includes(region2) && (best === null || all.length < best.size)) best = { name: r, size: all.length };
  }
  return best.name;
}

