function generate(rand, size) {
  const large = size === 'large';
  const total = large ? 3000 : 3 + Math.floor(rand() * 10);
  const pick = k => Math.floor(rand() * k);
  const used = new Set();
  const word = len => { let w = String.fromCharCode(65 + pick(26)); for (let i = 1; i < len; i++) w += String.fromCharCode(97 + pick(26)); return w; };
  const name = () => {
    for (;;) {
      let w = large ? word(3 + pick(8)) : word(1 + pick(3));
      if (rand() < 0.2) w += ' ' + word(1 + pick(large ? 8 : 3));
      if (!used.has(w)) { used.add(w); return w; }
    }
  };
  const names = [], kids = [];
  let internal = 0;
  for (let k = 0; k < total; k++) {
    names.push(name());
    kids.push([]);
    if (k === 0) continue;
    // Node 1 hangs off the root and node 2 off node 1, so there are always at least two lists.
    let p = k <= 2 ? k - 1 : -1;
    while (p < 0) {
      const c = rand() < 0.5 ? k - 1 - pick(Math.min(k, 4)) : pick(k);
      if (kids[c].length < 19 && (kids[c].length > 0 || internal < 1999)) p = c;
    }
    if (kids[p].length === 0) internal++;
    kids[p].push(k);
  }
  const regions = [];
  for (let k = 0; k < total; k++) if (kids[k].length) regions.push([names[k], ...kids[k].map(c => names[c])]);
  for (let i = regions.length - 1; i > 0; i--) { const j = pick(i + 1); [regions[i], regions[j]] = [regions[j], regions[i]]; }
  const a = pick(total);
  let b = pick(total - 1);
  if (b >= a) b++;
  return [regions, names[a], names[b]];
}
